import sys
MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M = data[0], data[1]
    best = [[0] * (N + 1) for _ in range(N + 1)]
    p = 2
    for _ in range(M):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        if l > best[x][r]:
            best[x][r] = l

    # For a fixed x and right endpoint r, keep the largest L among
    # constraints X=x whose right endpoint is at most r.
    for x in range(1, N + 1):
        row = best[x]
        for r in range(1, N + 1):
            if row[r - 1] > row[r]:
                row[r] = row[r - 1]

    comb = [[0] * (N + 1) for _ in range(N + 1)]
    for n in range(N + 1):
        comb[n][0] = comb[n][n] = 1
        for j in range(1, n):
            comb[n][j] = (comb[n - 1][j - 1] + comb[n - 1][j]) % MOD

    dp = [[0] * (N + 2) for _ in range(N + 2)]
    for i in range(1, N + 2):
        dp[i][i - 1] = 1

    for length in range(1, N + 1):
        for l in range(1, N - length + 2):
            r = l + length - 1
            total = 0
            for k in range(l, r + 1):
                # A constraint with X=k invalidates k as the maximum here
                # precisely when its whole interval is contained in [l,r].
                if best[k][r] >= l:
                    continue
                left_size = k - l
                right_size = r - k
                total += (comb[length - 1][left_size] *
                          dp[l][k - 1] * dp[k + 1][r])
            dp[l][r] = total % MOD

    print(dp[1][N])

