import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    mx = max(a)

    phi = list(range(mx + 1))
    for p in range(2, mx + 1):
        if phi[p] == p:
            for k in range(p, mx + 1, p):
                phi[k] -= phi[k] // p

    divisors = [[] for _ in range(mx + 1)]
    for d in range(1, mx + 1):
        for x in range(d, mx + 1, d):
            divisors[x].append(d)

    weighted_count = [0] * (mx + 1)
    ans = 0
    weight = 1
    out = []
    for x in a:
        c = 0
        for d in divisors[x]:
            c += phi[d] * weighted_count[d]
        c %= MOD
        ans = (2 * ans + c) % MOD
        out.append(str(ans))

        for d in divisors[x]:
            weighted_count[d] += weight
            if weighted_count[d] >= MOD:
                weighted_count[d] -= MOD
        weight = (weight * 2) % MOD

    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

