import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    values = data[1:]
    limit = max(values)

    # Smallest prime factor for every number up to the maximum input value.
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p

    nim_sum = 0
    for value in values:
        prime_factors = 0  # counted with multiplicity
        while value > 1:
            value //= spf[value]
            prime_factors += 1
        nim_sum ^= prime_factors

    print('Anna' if nim_sum else 'Bruno')

