from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        buckets = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            buckets[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        total = 0

        for r in range(1, n + 1):
            for a, i in buckets[r]:
                heapq.heappush(heap, (-a, i))

            if not heap:
                total += r
                continue

            neg_a, best_id = heapq.heappop(heap)
            best_a = -neg_a
            if heap:
                neg_second, second_id = heapq.heappop(heap)
                second_a = -neg_second
                heapq.heappush(heap, (neg_second, second_id))
            else:
                second_a = 0
            heapq.heappush(heap, (neg_a, best_id))

            total += r - best_a
            gains[best_id] += best_a - second_a

        return total + max(gains)

