class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1

        for i in range(1, n + 1):
            for k in range(min(i, x), 0, -1):
                # Put the new performer into one of k existing bands,
                # or start a band on one of the unused stages and choose its score.
                dp[k] = (dp[k] * k + dp[k - 1] * (x - k + 1) * y) % mod
            dp[0] = 0

        return sum(dp) % mod

