from math import comb

class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)

        def depth(x):
            d = 0
            while x > 1:
                x = x.bit_count()
                d += 1
            return d

        allowed = [False] * (L + 1)
        for t in range(1, L + 1):
            allowed[t] = depth(t) <= k - 1

        ans = 0
        used = 0
        for i, bit in enumerate(s):
            rem = L - i - 1
            if bit == '1':
                for t in range(1, L + 1):
                    need = t - used
                    if allowed[t] and 0 <= need <= rem:
                        ans = (ans + comb(rem, need)) % MOD
                used += 1
        return ans

