def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, x = data[0], data[1]
    U = data[2::2]
    D = data[3::2]
    total = sum(U) + sum(D)

    def feasible(h):
        lo = hi = None
        for u, d in zip(U, D):
            left = max(0, h - d)
            right = min(u, h)
            if lo is None:
                lo, hi = left, right
            else:
                lo, hi = max(left, lo - x), min(right, hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    high = min(u + d for u, d in zip(U, D)) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(total - n * low)

if __name__ == '__main__':
