from functools import lru_cache
from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((1, 1), (1, -1), (-1, -1), (-1, 1))

        @lru_cache(None)
        def dp(r, c, d, can_turn):
            value = grid[r][c]
            if value == 1:
                return 0
            wanted = 0 if value == 2 else 2
            best = 1
            choices = (d, (d + 1) % 4) if can_turn else (d,)
            for nd in choices:
                dr, dc = dirs[nd]
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == wanted:
                    best = max(best, 1 + dp(nr, nc, nd, can_turn and nd == d))
            return best

        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d, (dr, dc) in enumerate(dirs):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == 2:
                            ans = max(ans, 1 + dp(nr, nc, d, True))
        return ans

