from typing import List
import math

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))
        result = []
        prev = None

        for pos in range(n):
            chosen = None
            for x in sorted(odds | evens):
                if prev is not None and x % 2 == prev % 2:
                    continue

                odd_left = len(odds) - (x in odds)
                even_left = len(evens) - (x in evens)
                remaining = n - pos - 1
                next_parity = 1 - (x % 2)  # 1 for odd, 0 for even
                odd_slots = (remaining + 1) // 2 if next_parity == 1 else remaining // 2
                even_slots = remaining - odd_slots

                if odd_left == odd_slots and even_left == even_slots:
                    ways = math.factorial(odd_left) * math.factorial(even_left)
                else:
                    ways = 0

                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    break

            if chosen is None:
                return []

            result.append(chosen)
            if chosen in odds:
                odds.remove(chosen)
            else:
                evens.remove(chosen)
            prev = chosen

        return result

