class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k

        coeff = []
        for i in range(m):
            j = n - 1 - i
            if i == j:
                coeff.append(powers[i])
            else:
                coeff.append((powers[i] + powers[j]) % k)

        # dp[i][r]: the variables from i onward can contribute residue r.
        dp = [None] * (m + 1)
        dp[m] = bytearray([1] + [0] * (k - 1))
        for i in range(m - 1, -1, -1):
            reachable = bytearray(k)
            nxt = dp[i + 1]
            c = coeff[i]
            for r in range(k):
                if nxt[r]:
                    for digit in range(10):
                        reachable[(r + digit * c) % k] = 1
            dp[i] = reachable

        half = []
        prefix_residue = 0
        for i, c in enumerate(coeff):
            lowest = 1 if i == 0 else 0
            for digit in range(9, lowest - 1, -1):
                needed = (-prefix_residue - digit * c) % k
                if dp[i + 1][needed]:
                    half.append(str(digit))
                    prefix_residue = (prefix_residue + digit * c) % k
                    break

        first_half = ''.join(half)
        if n % 2:
            return first_half + first_half[:-1][::-1]
        return first_half + first_half[::-1]

