class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1

        n = len(s)
        answer = n

        # For a fixed final frequency k, dp[x] is the minimum cost after
        # processing the letters so far, with x characters carried to the
        # next letter.
        for k in range(1, max(counts) + 1):
            dp = {0: 0}
            for c in counts:
                ndp = {}
                for incoming, cost in dp.items():
                    available = c + incoming

                    # Make this letter's final count zero or k. Any excess
                    # can be deleted or carried forward.
                    for kept in (0, k):
                        if available >= kept:
                            excess = available - kept
                            base = cost
                            for outgoing in range(excess + 1):
                                total = base + excess - outgoing + outgoing
                                old = ndp.get(outgoing)
                                if old is None or total < old:
                                    ndp[outgoing] = total
                        else:
                            total = cost + kept - available
                            old = ndp.get(0)
                            if old is None or total < old:
                                ndp[0] = total
                dp = ndp
            answer = min(answer, min(dp.values()))

        return answer

