def solve_case(grid):
    h=len(grid); w=len(grid[0])
    # transpose if needed to minimize transfer width; tile rules invariant under transpose
    if w>h:
        grid=[''.join(grid[i][j] for i in range(h)) for j in range(w)]
        h,w=w,h
    n=1<<w
    ans=0
    for initial in range(n):
        dp={initial:1}
        for row in grid:
            nd={}
            for top,ways in dp.items():
                for start in (0,1):
                    left=start; bottom=0; ok=True
                    for j,ch in enumerate(row):
                        t=(top>>j)&1
                        if ch=='A':
                            right=left^1; b=t^1
                        else:
                            if left==t:
                                ok=False; break
                            right=left; b=t
                        if b: bottom|=1<<j
                        left=right
                    if ok and left==start:
                        nd[bottom]=(nd.get(bottom,0)+ways)%MOD
            dp=nd
            if not dp: break
        ans=(ans+dp.get(initial,0))%MOD
    return ans

def main():
    data=sys.stdin.buffer.read().split(); t=int(data[0]); p=1; out=[]
    for _ in range(t):
        h=int(data[p]); w=int(data[p+1]); p+=2
        grid=[data[p+i].decode() for i in range(h)]; p+=h
        out.append(str(solve_case(grid)))
    print('\n'.join(out))
main()

