from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        a, b, c = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        apos = occurrences(a)
        bpos = occurrences(b)
        cpos = occurrences(c)
        ans = n + 1
        for x in bpos:
            ai = bisect_right(apos, x - len(a)) - 1
            ci = bisect_left(cpos, x + len(b))
            if ai >= 0 and ci < len(cpos):
                ans = min(ans, cpos[ci] + len(c) - apos[ai])
        return -1 if ans == n + 1 else ans

