import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    val = [-1] * n
    ans = [0] * n
    for start in range(n):
        if val[start] != -1:
            continue
        val[start] = 0
        comp = [start]
        stack = [start]
        while stack:
            v = stack.pop()
            for u, z in adj[v]:
                expected = val[v] ^ z
                if val[u] == -1:
                    val[u] = expected
                    comp.append(u)
                    stack.append(u)
                elif val[u] != expected:
                    print(-1)
                    return

        shift = 0
        size = len(comp)
        for bit in range(30):
            ones = sum((val[v] >> bit) & 1 for v in comp)
            if ones * 2 > size:
                shift |= 1 << bit
        for v in comp:
            ans[v] = val[v] ^ shift

    print(*ans)

if __name__ == '__main__':
    main()

