import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, W = data[0], data[1]
    items = data[2:]
    neg = -(10**30)
    dp = [neg] * (W + 1)
    dp[0] = 0

    for i in range(n):
        w, v = items[2 * i], items[2 * i + 1]
        ndp = [neg] * (W + 1)
        for r in range(min(w, W + 1)):
            hull = deque()
            for t in range((W - r) // w + 1):
                idx = r + t * w
                val = dp[idx]
                if val != neg:
                    m = 2 * t
                    b = val - t * v - t * t
                    while len(hull) >= 2 and (hull[-1][1] - hull[-2][1]) * (hull[-1][0] - m) >= (b - hull[-1][1]) * (hull[-2][0] - hull[-1][0]):
                        hull.pop()
                    hull.append((m, b))

                while len(hull) >= 2 and hull[1][0] * t + hull[1][1] >= hull[0][0] * t + hull[0][1]:
                    hull.popleft()
                if hull:
                    ndp[idx] = -t * t + t * v + hull[0][0] * t + hull[0][1]
        dp = ndp

    print(max(dp))

if __name__ == '__main__':
    main()

