from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        postorder = []
        start = [0] * n
        size = [0] * n
        stack = [(0, 0)]
        while stack:
            v, state = stack.pop()
            if state == 0:
                start[v] = len(postorder)
                stack.append((v, 1))
                for child in reversed(children[v]):
                    stack.append((child, 0))
            else:
                postorder.append(s[v])
                size[v] = len(postorder) - start[v]

        text = ''.join(postorder)

        # d1[i]: odd palindrome radius centered at i, including text[i].
        d1 = [0] * n
        left, right = 0, -1
        for i in range(n):
            radius = 1 if i > right else min(d1[left + right - i], right - i + 1)
            while i - radius >= 0 and i + radius < n and text[i - radius] == text[i + radius]:
                radius += 1
            d1[i] = radius
            if i + radius - 1 > right:
                left, right = i - radius + 1, i + radius - 1

        # d2[i]: even palindrome radius centered immediately before i.
        d2 = [0] * n
        left, right = 0, -1
        for i in range(n):
