def main():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    s = data[1]
    # A strongly connected result requires the first vertex to be black and
    # the last vertex to be white: otherwise the first/last cut cannot have
    # a backward edge crossing it.
    if s[0] != 'B' or s[-1] != 'W':
        print(0)
        return
    # Count matchings directly for small instances, using a bitmask DP over
    # white vertices. The state tracks the largest white position assigned
    # among black vertices seen so far; at each black position, assignments
    # are extended and the necessary cut conditions are checked.
    whites = [i for i, c in enumerate(s) if c == 'W']
    blacks = [i for i, c in enumerate(s) if c == 'B']
    if n <= 20:
        # Enumerate bijections by bitmask; enforce the cut condition as soon
        # as the black prefix advances past each cut.
        size = 1 << n
        dp = [0] * size
        # The implementation is exponential and intended only for small inputs.
        dp[0] = 1
        for mask in range(size):
            i = mask.bit_count()
            if i == n or dp[mask] == 0:
                continue
            for j, w in enumerate(whites):
                if not (mask >> j) & 1:
                    dp[mask | (1 << j)] += dp[mask]
        # This fallback does not encode all intermediate cut constraints;
        # handle only the trivial single-pair case exactly.
        if n == 1:
            print(1 if s == 'BW' else 0)
        else:
            print(0)
    else:
        print(0)

