class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        # For an endpoint j, a valid subarray starts at i iff
        # j - i is divisible by k, i.e. i and j have same remainder.
        min_prefix = [None] * k
        min_prefix[0] = 0
        prefix = 0
        best = None

        for j, value in enumerate(nums, 1):
            prefix += value
            r = j % k
            if min_prefix[r] is not None:
                candidate = prefix - min_prefix[r]
                if best is None or candidate > best:
                    best = candidate
            if min_prefix[r] is None or prefix < min_prefix[r]:
                min_prefix[r] = prefix

        return best

