class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        # dp[i] is the length produced by one original character i
        # after the current number of transformations.
        dp = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i] = dp[i + 1]
            nxt[25] = (dp[0] + dp[1]) % mod
            dp = nxt
        return sum(dp[ord(c) - ord('a')] for c in s) % mod

