import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10 ** len(str(n))
        low = limit // 10 if limit > 10 else 1

        is_prime = bytearray(b'\x01') * limit
        is_prime[0] = 0
        if limit > 1:
            is_prime[1] = 0
        for p in range(2, int((limit - 1) ** 0.5) + 1):
            if is_prime[p]:
                start = p * p
                count = (limit - 1 - start) // p + 1
                is_prime[start:limit:p] = b'\x00' * count

        if is_prime[n] or is_prime[m]:
            return -1

        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist.get(value):
                continue
            if value == m:
                return cost

            place = 1
            while place < limit:
                digit = (value // place) % 10
                if digit < 9:
                    nxt = value + place
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                if digit > 0:
                    nxt = value - place
                    if nxt >= low and not is_prime[nxt]:
                        new_cost = cost + nxt
                        if new_cost < dist.get(nxt, float('inf')):
                            dist[nxt] = new_cost
                            heapq.heappush(heap, (new_cost, nxt))
                place *= 10

        return -1

