class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        def z_function(a):
            m = len(a)
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k <= right:
                    z[k] = min(right - k + 1, z[k - left])
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] - 1 > right:
                    left, right = k, k + z[k] - 1
            return z

        prefix_z = z_function(nums)
        answer = 0

        # i is the length of the first part, d the length of the second.
        for i in range(1, n - 1):
            suffix_z = z_function(nums[i:])
            first_is_prefix = prefix_z[i] >= i
            for d in range(1, n - i):
                # First part is a prefix of second part.
                first_condition = first_is_prefix and d >= i
                # Second part is a prefix of third part.
                second_condition = 2 * d <= n - i and suffix_z[d] >= d
                if first_condition or second_condition:
                    answer += 1

        return answer

