    dp = [neg, neg]  # best sum of survivors ending at odd/even index
    for i, x in enumerate(a, 1):
        ndp = dp[:]
        if i & 1:
            ndp[0] = max(ndp[0], x)
            if dp[1] != neg:
                ndp[0] = max(ndp[0], dp[1] + x)
        else:
            if dp[0] != neg:
                ndp[1] = max(ndp[1], dp[0] + x)
        dp = ndp

    # The final stack height has the same parity as N.
    ans = dp[0] if n & 1 else max(0, dp[1])
    print(ans)

if __name__ == '__main__':
    main()

