from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        removable = bytearray(n)
        for i in targetIndices:
            removable[i] = 1

        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            ndp = dp[:]  # Keep this character without using it in the subsequence.
            if removable[i]:
                for j in range(m + 1):
                    if dp[j] != neg:
                        ndp[j] = max(ndp[j], dp[j] + 1)
            for j in range(m):
                if ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp

        return dp[m]

